import FormModal from '../../common/components/FormModal';
import ItemList from 'flarum/common/utils/ItemList';
import Button from 'flarum/common/components/Button';
import Switch from 'flarum/common/components/Switch';
import Stream from 'flarum/common/utils/Stream';
import app from 'flarum/admin/app';
export default class EditBadgeCategoryModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);

    // Badge model
    this.badgeCategory = this.attrs.badgeCategory ? this.attrs.badgeCategory : app.store.createRecord('badge-categories');

    // Name
    this.name = Stream(this.badgeCategory.name());

    // Description
    this.description = Stream(this.badgeCategory.description());

    // Is enabled
    this.isTable = Stream(this.badgeCategory.exists ? this.badgeCategory.isTable() : true);

    // Is enabled
    this.isEnabled = Stream(this.badgeCategory.exists ? this.badgeCategory.isEnabled() : true);
  }
  className() {
    return 'Modal--small';
  }
  title() {
    return app.translator.trans(`v17development-flarum-badges.admin.${this.badgeCategory.exists ? 'update_category' : 'create_category'}`);
  }
  content() {
    return [m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, this.data().toArray())), m("div", {
      className: "Modal-footer"
    }, Button.component({
      type: 'submit',
      className: 'Button Button--primary',
      loading: this.loading
    }, app.translator.trans('core.admin.settings.submit_button')))];
  }
  data() {
    const items = new ItemList();
    items.add('name', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('v17development-flarum-badges.admin.badge_category.name'), ":"), m("input", {
      className: "FormControl",
      placeholder: app.translator.trans('v17development-flarum-badges.admin.badge_category.name'),
      bidi: this.name
    })), 50);
    items.add('description', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('v17development-flarum-badges.admin.badge_category.description'), ":"), m("textarea", {
      className: "FormControl",
      placeholder: app.translator.trans('v17development-flarum-badges.admin.badge_category.description'),
      bidi: this.description
    })), 50);

    // Enabled
    items.add('blockview', m("div", {
      className: "Form-group"
    }, Switch.component({
      state: this.isTable() === false,
      onchange: val => this.isTable(!val)
    }, [m("b", null, app.translator.trans('v17development-flarum-badges.admin.badge_category.blockview')), m("div", {
      className: "helpText"
    }, app.translator.trans('v17development-flarum-badges.admin.badge_category.blockview_description'))])), 50);

    // Enabled
    items.add('enabled', m("div", {
      className: "Form-group"
    }, Switch.component({
      state: this.isEnabled() == true,
      onchange: val => this.isEnabled(val)
    }, [m("b", null, app.translator.trans('v17development-flarum-badges.admin.badge_category.enabled')), m("div", {
      className: "helpText"
    }, app.translator.trans('v17development-flarum-badges.admin.badge_category.enabled_description'))])), 50);
    return items;
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    this.badgeCategory.save({
      name: this.name(),
      description: this.description(),
      isTable: this.isTable(),
      isEnabled: this.isEnabled()
    }).then(() => {
      this.hide();
      if (this.attrs.onCreate) {
        this.attrs.onCreate();
      }
    }, response => {
      this.loading = false;
      this.handleErrors(response);
    });
  }
}
flarum.reg.add('itqan-user-badges', 'admin/components/EditBadgeCategoryModal', EditBadgeCategoryModal);